INSERT INTO "classifications" VALUES(2195,'claude-haiku-5-5','2026-10-22T03:09:39Z',0,0.9,0,'{"areas": ["other"], "confidence": 0.9, "countries": ["JP"], "event_date": "2026-10-21", "institutions": [{"country": "JP", "name": "NTT", "short_name": "NTT", "type": "private_sector"}, {"country": "JP", "name": "福岡市管工事協同組合", "short_name": null, "type": "NGO"}], "language": "ja", "news_type": "pilot_research", "original_title": "NTT、光ファイバとAIで漏水位置を特定 15分で熟練者並み精度", "primary_area": "other", "relevant": false, "review": false, "summary_en": "NTT demonstrated, with the Fukuoka City pipe works cooperative, an optical fiber sensing and AI approach to locate leaks in urban water supply pipes. The reported accuracy is within 75 cm horizontally with an 88% correct rate. This is a water utility infrastructure application rather than weather, climate, early warning or disaster risk reduction, so it is not relevant to WMO monitoring.", "summary_original": "NTTは光ファイバセンシングとAIを活用し、福岡市内で給水管の漏水位置特定を実証した。水平誤差75cm以内、正解率88%を達成したという。", "system_name": null, "techniques": ["ml_dl"], "title_en": "NTT identifies water pipe leak locations with optical fiber and AI, achieving accuracy comparable to experts in 15 minutes", "value_added": "Locates water supply pipe leaks in about 15 minutes with accuracy comparable to experts (horizontal error within 75 cm, 88% correct rate).", "value_types": ["speed", "accuracy"], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(2203,'claude-haiku-5-5','2026-10-22T03:09:16Z',1,0.8,0,'{"areas": ["forecasting", "warnings"], "confidence": 0.8, "countries": ["JP"], "event_date": "2026-10-20", "institutions": [{"country": "JP", "name": "Weathernews Inc.", "short_name": "Weathernews", "type": "private_sector"}], "language": "ja", "news_type": "other", "original_title": "台風30号 物理モデルとAI予測に大きな差 AIモデルは北東へ転向する計算も - ウェザーニュース", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "Weathernews reports that for Typhoon No. 30, approaching Okinawa, the track after passing south of Okinawa differs between physical numerical models and AI forecast models, with the AI model calculating a turn toward the northeast. Residents in Okinawa are advised to watch for strengthening rain and wind.", "summary_original": "沖縄の南を通過後の台風30号の進路について、物理モデルとAI予測モデルで傾向に違いがあり、AIモデルは北東への転向を計算していると伝えている。沖縄では雨や風の強まりに警戒が必要とされている。", "system_name": null, "techniques": ["ai_weather_model"], "title_en": "Typhoon No. 30: large difference between physical model and AI forecasts; AI model calculates turn to the northeast", "value_added": null, "value_types": ["accuracy"], "wmo_regions": ["II"]}');
