INSERT INTO "classifications" VALUES(3381,'claude-haiku-5-5','2026-10-27T04:07:48Z',1,0.85,0,'{"areas": ["climate_services"], "confidence": 0.85, "countries": ["IN"], "event_date": "2026-10-25", "institutions": [], "language": "en", "news_type": "pilot_research", "original_title": "Simple Weather Patterns Better at Predicting Sunshine in Jammu and Kashmir Than Complex AI Models: Study", "primary_area": "climate_services", "relevant": true, "review": false, "summary_en": "A 2026 study reported that simple linear regression predicts sunshine duration in Jammu and Kashmir more accurately than complex machine-learning models. The findings challenge the assumption that advanced algorithms always produce better climate estimates. The item is relevant because it compares ML approaches for climate-related estimation, though no operational institution is named.", "summary_original": null, "system_name": null, "techniques": ["ml_dl"], "title_en": "Simple Weather Patterns Better at Predicting Sunshine in Jammu and Kashmir Than Complex AI Models: Study", "value_added": "Simple linear regression predicted sunshine duration more accurately than complex machine-learning models in the study.", "value_types": ["accuracy"], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(3480,'claude-haiku-5-5','2026-10-27T04:07:42Z',1,0.85,0,'{"areas": ["communication", "operations"], "confidence": 0.85, "countries": ["JP"], "event_date": "2026-10-26", "institutions": [{"country": "JP", "name": "Weathernews Inc.", "short_name": "Weathernews", "type": "private_sector"}], "language": "ja", "news_type": "policy_guidance", "original_title": "AI全振りで気象サービス変革 民間だからこそAIネーティブ化推進", "primary_area": "operations", "relevant": true, "review": false, "summary_en": "Japanese private weather company Weathernews reports record sales for 17 consecutive periods and plans to transform into an ''AI Fusion Company'' by deploying AI agents across all its products. The strategy aims to build a hybrid team of meteorological professionals combining human expertise with AI. The article focuses on corporate strategy rather than a specific AI weather model.", "summary_original": "過去最高売上高を17期連続で更新し、営業利益率も21％超となるなど好調な同社を牽引する。全プロダクトへのAIエージェント投入など「AI Fusion Company」への転換を掲げ、人の能力とAIを融合させた「融合型の気象プロフェッショナル集団」を目指す。", "system_name": null, "techniques": ["llm_genai"], "title_en": "Weather service transformation fully powered by AI; AI-native promotion as a private company", "value_added": "Company transformation into an ''AI Fusion Company'' combining human meteorologists with AI agents across all products, aiming to boost business performance.", "value_types": ["efficiency", "other"], "wmo_regions": ["II"]}');
