INSERT INTO "classifications" VALUES(3573,'claude-haiku-5-5','2026-10-27T04:07:45Z',0,0.95,0,'{"areas": ["other"], "confidence": 0.95, "countries": [], "event_date": "2026-10-26", "institutions": [{"country": null, "name": "Anthropic", "short_name": "Anthropic", "type": "private_sector"}], "language": "es", "news_type": "other", "original_title": "Anthropic admite que los sistemas de IA podrían plantear riesgos “catastróficos o existenciales para la humanidad”", "primary_area": "other", "relevant": false, "review": false, "summary_en": "Anthropic''s IPO prospectus acknowledges that AI systems could pose catastrophic or existential risks, and mentions climate change affecting its cost structure. The item concerns corporate risk disclosure and general AI safety, not AI applied to weather, water, climate, early warning or disaster risk reduction.", "summary_original": "El folleto de salida a Bolsa de Anthropic reconoce que los sistemas de IA podrían plantear riesgos catastróficos o existenciales, y menciona que el cambio climático podría afectar a su estructura de costes. La noticia trata sobre divulgación de riesgos corporativos y seguridad general de la IA, no sobre IA aplicada al tiempo, agua, clima o alerta temprana.", "system_name": null, "techniques": [], "title_en": "Anthropic admits AI systems could pose \"catastrophic or existential risks for humanity\"", "value_added": null, "value_types": [], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(3660,'claude-haiku-5-5','2026-10-28T04:06:42Z',1,0.8,0,'{"areas": ["other"], "confidence": 0.8, "countries": [], "event_date": "2026-10-27", "institutions": [], "language": "en", "news_type": "pilot_research", "original_title": "Event-level attribution of wildfire ignitions using a machine-learning framework", "primary_area": "other", "relevant": true, "review": false, "summary_en": "A study introduces a machine-learning classification framework (MLCF) that attributes the cause of wildfire ignitions as either human- or lightning-induced at a global, event-level scale. The work is research-oriented and relevant to disaster risk reduction and wildfire management, though it does not specify an operational NMHS or early warning agency deployment.", "summary_original": null, "system_name": "MLCF (machine-learning classification framework)", "techniques": ["ml_dl"], "title_en": "Event-level attribution of wildfire ignitions using a machine-learning framework", "value_added": "Attributes wildfire ignition cause (human vs lightning) at global event level, supporting wildfire risk and disaster management understanding.", "value_types": ["accuracy", "coverage"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(3691,'claude-haiku-5-5','2026-10-28T04:06:30Z',1,0.85,0,'{"areas": ["warnings", "hydrology"], "confidence": 0.85, "countries": ["US"], "event_date": "2026-10-26", "institutions": [{"country": null, "name": "Geolava", "short_name": "Geolava", "type": "private_sector"}], "language": "en", "news_type": "other", "original_title": "Will your neighborhood flood during a hurricane? An expert explains how AI can predict vulnerable areas before extreme weather strikes", "primary_area": "warnings", "relevant": true, "review": false, "summary_en": "An interview with the CEO of Geolava describes a spatial AI technology that predicts which areas could flood during hurricanes and other extreme weather. The article states the technology has already helped people in Florida. The snippet gives no detail on the underlying model or data.", "summary_original": null, "system_name": "Geolava spatial AI", "techniques": ["ml_dl"], "title_en": "Will your neighborhood flood during a hurricane? An expert explains how AI can predict vulnerable areas before extreme weather strikes", "value_added": "Predicts which neighbourhoods could flood during extreme weather, before it strikes, and has already assisted people in Florida, as stated in the article.", "value_types": ["lead_time", "accuracy", "coverage"], "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(3701,'claude-haiku-5-5','2026-10-28T04:06:32Z',1,0.8,0,'{"areas": ["observations", "forecasting", "warnings"], "confidence": 0.8, "countries": ["US"], "event_date": "2026-10-27", "institutions": [], "language": "en", "news_type": "pilot_research", "original_title": "AI and satellite data could give Florida earlier warnings of toxic red tides", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "Research reported by Phys.org suggests that AI applied to satellite data could give Florida earlier warnings of toxic red tide algal blooms, which harm respiratory health, fish and coastal neurological health. The article covers a research approach rather than an operational system, and the snippet does not name specific institutions or models.", "summary_original": null, "system_name": null, "techniques": ["ml_dl"], "title_en": "AI and satellite data could give Florida earlier warnings of toxic red tides", "value_added": "Earlier warnings of toxic red tide blooms by combining AI with satellite data.", "value_types": ["lead_time", "accuracy"], "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(3794,'claude-haiku-5-5','2026-10-28T04:06:37Z',0,0.9,0,'{"areas": ["other"], "confidence": 0.9, "countries": [], "event_date": "2026-10-27", "institutions": [], "language": "ja", "news_type": "other", "original_title": "AIエージェント導入時に見極める、「ワークフロー」で十分な業務", "primary_area": "other", "relevant": false, "review": false, "summary_en": "A Nikkei xTECH column discussing when enterprise tasks are better handled by predictable workflows than AI agents, giving examples like minutes summarisation and FAQ answering. It does not concern weather, water, climate, early warning or disaster risk reduction.", "summary_original": "手順が決まっていて分岐を事前設計できる業務は、AIエージェントより予測可能で監査しやすいワークフローが向くとする記事。議事録整形・要約、問い合わせの振り分け、定型レポート生成などが例として挙げられている。気象・防災分野には言及がない。", "system_name": null, "techniques": [], "title_en": "Business tasks sufficient for workflows rather than AI agents when introducing AI agents", "value_added": null, "value_types": [], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(3838,'claude-haiku-5-5','2026-10-28T04:06:27Z',1,0.85,0,'{"areas": ["forecasting"], "confidence": 0.85, "countries": ["JP"], "event_date": "2026-10-28", "institutions": [{"country": "JP", "name": "UMK テレビ宮崎", "short_name": "UMK", "type": "other"}], "language": "ja", "news_type": "other", "original_title": "台風30号「AI予測」が勝った!? 従来予測とAI予測の違いを気象予報士が解説｜関連記事｜古山さんのお天気ポケット｜UMKテレビ宮崎", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "A Japanese regional TV station (UMK) explains that for Typhoon No. 30, AI forecasts showed a track toward Kyushu from 18 October and updated with greater confidence on 19 October, whereas many conventional models predicted a path toward the continent. The article is a media explanation of AI typhoon track forecasting performance rather than an institutional deployment.", "summary_original": "台風30号では、18日の時点でAIが九州に向かうルートを早い段階から示し、19日にはより強い確信で九州方面へ更新したと解説されている。従来モデルの多くは大陸方面を予測していた。", "system_name": null, "techniques": ["ai_weather_model"], "title_en": "Typhoon No. 30 \"AI forecast\" wins? Weather forecaster explains differences between conventional and AI forecasts", "value_added": "AI forecasts indicated a track toward Kyushu earlier and with more confidence than many conventional models, which predicted the continental direction.", "value_types": ["lead_time", "accuracy"], "wmo_regions": ["II"]}');
