INSERT INTO "classifications" VALUES(4679,'claude-haiku-5-5','2026-10-31T04:07:50Z',1,0.95,0,'{"areas": ["climate_services", "forecasting"], "confidence": 0.95, "countries": ["ES"], "event_date": "2026-10-30", "institutions": [{"country": "ES", "name": "Agencia Estatal de Meteorología (AEMET)", "short_name": "AEMET", "type": "NMHS"}], "language": "es", "news_type": "operational_implementation", "original_title": "Nuevas predicciones estacionales de alta resolución mediante técnicas de aprendi...", "primary_area": "climate_services", "relevant": true, "review": false, "summary_en": "AEMET''s State Climate Services Platform (PESC) has incorporated a new downscaling methodology based on advanced machine learning techniques to improve seasonal forecasts. The method provides climate information with greater spatial detail for Spain.", "summary_original": "La Plataforma Estatal de Servicios Climáticos de AEMET (PESC) incorpora una nueva metodología de regionalización basada en machine learning que mejora las predicciones estacionales con mayor detalle espacial para España.", "system_name": null, "techniques": ["ml_dl"], "title_en": "New high-resolution seasonal forecasts using machine learning techniques", "value_added": "Seasonal climate information with finer spatial detail for Spain through a machine-learning-based downscaling methodology.", "value_types": ["resolution", "accuracy"], "wmo_regions": ["VI"]}');
INSERT INTO "classifications" VALUES(4805,'claude-haiku-5-5','2026-11-01T04:06:57Z',1,0.95,0,'{"areas": ["forecasting", "warnings"], "confidence": 0.95, "countries": ["CN"], "event_date": "2026-10-30", "institutions": [{"country": "CN", "name": "China Meteorological Administration", "short_name": "CMA", "type": "NMHS"}], "language": "en", "news_type": "model_release", "original_title": "AI models for extreme weather forecasts built - Chinadaily.com.cn", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "China has unveiled two AI models for extreme weather forecasting built on Fengyun satellite data. One targets short-term warnings of severe convective weather, predicting its occurrence, development and intensity four hours ahead.", "summary_original": null, "system_name": null, "techniques": ["ml_dl", "ai_weather_model"], "title_en": "AI models for extreme weather forecasts built - Chinadaily.com.cn", "value_added": "Predicts occurrence, development and intensity of severe convective weather four hours in advance using Fengyun satellite data.", "value_types": ["lead_time", "accuracy"], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4833,'claude-haiku-5-5','2026-11-01T04:07:05Z',0,0.3,1,'{"areas": ["other"], "confidence": 0.3, "countries": ["JP"], "event_date": "2026-11-13", "institutions": [{"country": "JP", "name": "AIデータ株式会社", "short_name": null, "type": "private_sector"}], "language": "ja", "news_type": "event_conference", "original_title": "災害情報・インフラデータをAIでつなぎ、防災・国土強靱化の新たな可能性を探る！「AIエージェント×AX・FDEフォーラム Nov 成長戦略17分野～防災・国土強靭化～」 11/13開催", "primary_area": "other", "relevant": false, "review": true, "summary_en": "A private company, AI Data Inc., announces a November 13, 2026 forum on AI agents and disaster prevention/national resilience, linking disaster information and infrastructure data. The snippet provides only a event announcement with no concrete AI deployment by an NMHS, early warning agency, or other relevant institution.", "summary_original": "AIデータ株式会社が、2026年11月13日開催の防災・国土強靱化をテーマとしたAIフォーラムを案内している。災害情報とインフラデータの連携による新たな可能性が議論される予定だが、具体的なAI導入事例は示されていない。", "system_name": null, "techniques": ["other"], "title_en": "Connecting disaster information and infrastructure data with AI to explore new possibilities for disaster prevention and national resilience: ''AI Agent x AX/FDE Forum Nov Growth Strategy 17 Fields - Disaster Prevention and National Resilience'' held 11/13", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4834,'claude-haiku-5-5','2026-11-01T04:07:09Z',1,0.6,0,'{"areas": ["operations", "warnings"], "confidence": 0.6, "countries": ["JP"], "event_date": "2026-11-13", "institutions": [{"country": "JP", "name": "AIデータ株式会社", "short_name": null, "type": "private_sector"}], "language": "ja", "news_type": "event_conference", "original_title": "AIで防災・国土強靱化を変革、11/13フォーラム開催", "primary_area": "operations", "relevant": true, "review": false, "summary_en": "AIデータ株式会社 announced an AI agent and AX (AI transformation) forum on 13 November 2026 focused on applying AI to disaster prevention and national resilience (kokudo kyōjinka). The item is a promotional event announcement; no specific AI model or operational deployment by a meteorological or disaster agency is described.", "summary_original": "AIデータ株式会社は、2026年11月13日に防災・国土強靱化分野のAI活用とAX推進をテーマとした「AIエージェント×AX・FDEフォーラム」を開催すると発表した。", "system_name": null, "techniques": ["other"], "title_en": "AI to transform disaster prevention and national resilience; forum to be held 11/13", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(4835,'claude-haiku-5-5','2026-11-01T04:07:07Z',0,0.95,0,'{"areas": ["warnings"], "confidence": 0.95, "countries": ["AR"], "event_date": "2026-10-31", "institutions": [{"country": "AR", "name": "Servicio Meteorológico Nacional", "short_name": "SMN", "type": "NMHS"}], "language": "es", "news_type": "other", "original_title": "Mendoza arranca noviembre con alerta amarilla por tormentas: qué zonas están afectadas", "primary_area": "warnings", "relevant": false, "review": false, "summary_en": "Argentina''s National Meteorological Service issued a yellow storm alert for parts of San Rafael and central and eastern Mendoza via its early warning system, warning of strong storms, possible hail and heavy rainfall. The item involves no artificial intelligence.", "summary_original": "El Servicio Meteorológico Nacional emitió alerta amarilla por tormentas para gran parte de San Rafael y el centro y este de Mendoza, a través de su Sistema de Alerta Temprana, por tormentas fuertes, granizo y lluvias intensas.", "system_name": null, "techniques": [], "title_en": "Mendoza starts November with yellow storm alert: which areas are affected", "value_added": null, "value_types": [], "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(4836,'claude-haiku-5-5','2026-11-01T04:07:00Z',0,0.95,0,'{"areas": ["climate_services"], "confidence": 0.95, "countries": ["AR"], "event_date": "2026-11-01", "institutions": [{"country": "AR", "name": "Servicio Meteorológico Nacional", "short_name": "SMN", "type": "NMHS"}], "language": "es", "news_type": "other", "original_title": "El SMN prevé un trimestre más caluroso y con lluvias moderadas en Tucumán - Los Primeros TV", "primary_area": "climate_services", "relevant": false, "review": false, "summary_en": "Argentina''s National Meteorological Service (SMN) issued its probabilistic consensus seasonal climate outlook for November 2026 to January 2027, forecasting above-average temperatures in Tucumán and the NOA region, and a yellow rainfall alert for Tucumán with 20-40 mm accumulations. The item describes conventional seasonal forecasting and warnings with no mention of artificial intelligence.", "summary_original": "El SMN publicó su pronóstico climático trimestral probabilístico por consenso para noviembre de 2026 a enero de 2027, anticipando temperaturas por encima del promedio en Tucumán y el NOA. El SMN también informó que Tucumán está bajo alerta amarilla por precipitaciones, con acumulados de 20 a 40 mm.", "system_name": null, "techniques": [], "title_en": "The SMN forecasts a warmer quarter with moderate rain in Tucumán", "value_added": null, "value_types": [], "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(4837,'claude-haiku-5-5','2026-11-01T04:07:02Z',1,0.9,0,'{"areas": ["forecasting"], "confidence": 0.9, "countries": [], "event_date": "2026-10-24", "institutions": [{"country": "US", "name": "Massachusetts Institute of Technology", "short_name": "MIT", "type": "research"}], "language": "es", "news_type": "pilot_research", "original_title": "El avance que desafía los límites del caos atmosférico: una IA afina las previsiones hasta seis semanas antes", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "An international team including MIT demonstrated a new artificial intelligence system that improves weather forecasts between 2 and 6 weeks ahead, including for anticipating floods and extreme events. The system can identify favourable conditions for extreme episodes several weeks in advance, though it does not predict all their specifics.", "summary_original": "Un equipo internacional con participación del MIT demostró que una nueva inteligencia artificial mejora los pronósticos meteorológicos entre 2 y 6 semanas, incluso para anticipar inundaciones y episodios extremos. El sistema podría identificar con varias semanas de antelación condiciones favorables para episodios extremos, aunque no predice todos sus detalles.", "system_name": null, "techniques": ["ml_dl"], "title_en": "The advance that challenges the limits of atmospheric chaos: an AI sharpens forecasts up to six weeks ahead", "value_added": "Improves weather forecasts by 2 to 6 weeks, including anticipating floods and extreme events, though it does not predict all their details.", "value_types": ["lead_time", "accuracy"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(5019,'claude-haiku-5-5','2026-11-02T04:10:12Z',0,0.9,0,'{"areas": ["other"], "confidence": 0.9, "countries": [], "event_date": "2026-10-30", "institutions": [{"country": "US", "name": "Google", "short_name": "Google", "type": "private_sector"}], "language": "ja", "news_type": "pilot_research", "original_title": "Google、衛星軌道上のAIから俳句の受信に初成功", "primary_area": "other", "relevant": false, "review": false, "summary_en": "Google reported that Project Suncatcher, a research project to build AI compute infrastructure in space, received its first response from a TPU in orbit. The item concerns space-based AI computing rather than weather, water, climate, early warning or disaster risk reduction applications.", "summary_original": "Googleは10月30日、宇宙空間にAI向けの計算基盤を構築する研究プロジェクト「Project Suncatcher」において、軌道上のTPUから初めての応答が得られたと報告した。", "system_name": "Project Suncatcher", "techniques": ["ml_dl", "other"], "title_en": "Google achieves first haiku reception from AI in satellite orbit", "value_added": null, "value_types": [], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(5023,'claude-haiku-5-5','2026-11-02T04:09:58Z',0,0.95,0,'{"areas": ["other"], "confidence": 0.95, "countries": ["JP"], "event_date": "2026-11-02", "institutions": [], "language": "ja", "news_type": "other", "original_title": "警報・注意報 - 日本気象協会 tenki.jp", "primary_area": "other", "relevant": false, "review": false, "summary_en": "A tenki.jp warnings page reports that no special warnings or warnings are in effect, a debris-flow advisory is shown for Akita Prefecture, and typhoon No. 31 is bringing high waves and strengthening winds to the Ogasawara Islands. The item contains no mention of artificial intelligence.", "summary_original": "tenki.jpの警報・注意報ページは、特別警報・警報は発表されていないものの、秋田県に土砂災害注意報が出ており、台風31号による小笠原諸島の高波と風の強まりを伝えているとするものです。AIに関する記述はありません。", "system_name": null, "techniques": [], "title_en": "Warnings and advisories - Japan Weather Association tenki.jp", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(5024,'claude-haiku-5-5','2026-11-02T04:10:03Z',0,0.95,0,'{"areas": ["other"], "confidence": 0.95, "countries": ["JP"], "event_date": "2026-11-02", "institutions": [], "language": "ja", "news_type": "other", "original_title": "11月2日の緊急要請で何が起こる？政府発表と備蓄の意味をわかりやすく解説 - 気になるアノこと", "primary_area": "other", "relevant": false, "review": false, "summary_en": "A blog post explaining the planned launch of Japan''s disaster prevention agency and an emergency request on 2 November 2026, noting that no official government or JMA announcement predicts earthquakes, war or cyberattacks on that date. The item does not describe any AI use for weather, water, climate, early warning or disaster management, so it is not relevant.", "summary_original": "2026年11月2日予定の防災庁発足と緊急要請について解説し、政府や気象庁の公表情報には同日の地震・戦争・サイバー攻撃の予告はないと記した記事。AIに関する内容は含まれない。", "system_name": null, "techniques": [], "title_en": "What will happen with the emergency request on November 2? A plain-language explanation of the government announcement and stockpiles", "value_added": null, "value_types": [], "wmo_regions": ["II"]}');
