INSERT INTO "classifications" VALUES(5029,'claude-haiku-5-5','2026-11-02T04:10:17Z',0,0.8,0,'{"areas": ["observations"], "confidence": 0.8, "countries": ["GB", "US"], "event_date": "2026-11-02", "institutions": [{"country": "GB", "name": "Menapia", "short_name": null, "type": "private_sector"}], "language": "es", "news_type": "pilot_research", "original_title": "Con El Niño disparado y más riesgo de tormentas en Europa, los meteorólogos prueban drones para afinar sus previsiones", "primary_area": "observations", "relevant": false, "review": false, "summary_en": "Researchers in the United States and the United Kingdom are testing drones that collect atmospheric data in real time, including within clouds, to improve forecasts. Trials between June and November 2026 were conducted in Yorkshire with the company Menapia. The item does not clearly state an AI component, so its relevance to AI-supported operations is uncertain.", "summary_original": "Investigadores de Estados Unidos y el Reino Unido desarrollan drones capaces de recopilar información atmosférica en tiempo real, incluso dentro de las nubes, para mejorar pronósticos. Las pruebas se realizaron en Yorkshire con la empresa Menapia.", "system_name": null, "techniques": [], "title_en": "With El Niño surging and more storm risk in Europe, meteorologists test drones to refine their forecasts", "value_added": "Drones collect real-time atmospheric data, including inside clouds, to improve forecasts and anticipate storms and extreme events.", "value_types": ["accuracy", "lead_time"], "wmo_regions": ["IV", "VI"]}');
