INSERT INTO "classifications" VALUES(6285,'claude-haiku-5-5','2026-11-07T04:09:30Z',1,0.9,0,'{"areas": ["forecasting", "communication"], "confidence": 0.9, "countries": ["BD", "ET", "IN", "KE", "NG", "PK"], "event_date": "2026-11-07", "institutions": [{"country": "US", "name": "University of Chicago", "short_name": "UChicago", "type": "research"}], "language": "en", "news_type": "partnership_funding", "original_title": "HPCwire - Since 1987", "primary_area": "communication", "relevant": true, "review": false, "summary_en": "The University of Chicago''s Human-Centered Weather Forecasts initiative sent AI-based forecasts by text message to tens of millions of farmers in Africa and South Asia from 2024 to 2026. The forecasts correctly predicted an unusual stall in seasonal rains, giving farmers early warning. The article also reports a $10M grant to build an open-source AI weather forecasting platform.", "summary_original": null, "system_name": null, "techniques": ["ai_weather_model"], "title_en": "UChicago receives $10M grant to build open-source AI weather forecasting platform", "value_added": "AI forecasts delivered by text message to tens of millions of farmers gave early warning of an unusual stall in seasonal rains.", "value_types": ["lead_time", "accessibility", "coverage"], "wmo_regions": ["I", "II"]}');
