INSERT INTO "classifications" VALUES(6758,'claude-haiku-5-5','2026-11-09T04:09:53Z',1,0.9,0,'{"areas": ["forecasting", "communication"], "confidence": 0.9, "countries": ["JP"], "event_date": "2026-11-09", "institutions": [{"country": "JP", "name": "ウェザーニュース", "short_name": "Weathernews", "type": "private_sector"}], "language": "ja", "news_type": "operational_implementation", "original_title": "【外出や現場の雨対策に】ウェザーニュースの「マイ天気」が進化！AIが1〜3時間先の雨雲の動きをピンポイント予測", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "Weathernews has added an AI-based function to its ''My Weather'' app that predicts rain cloud movement 1-3 hours ahead at pinpoint locations. The article notes the feature improves forecasting precision and does not automatically issue municipal evacuation orders.", "summary_original": "ウェザーニュースの「マイ天気」がAIで1〜3時間先の雨雲の動きをピンポイント予測する機能を実装したと報じられています。記事では、この機能は予測の高度化であり自治体の避難指示を自動発令するものではないと説明されています。", "system_name": null, "techniques": ["ml_dl"], "title_en": "Weathernews'' ''My Weather'' evolves: AI predicts rain clouds 1-3 hours ahead for pinpoint local forecasts for outdoor activities and field work", "value_added": "Pinpoint rain cloud movement prediction 1-3 hours ahead for specific locations, enhancing forecast precision for users.", "value_types": ["accuracy", "lead_time", "resolution"], "wmo_regions": ["II"]}');
INSERT INTO "classifications" VALUES(6759,'claude-haiku-5-5','2026-11-09T04:09:51Z',0,0.97,0,'{"areas": ["warnings"], "confidence": 0.97, "countries": ["AR"], "event_date": "2026-11-09", "institutions": [{"country": "AR", "name": "Servicio Meteorológico Nacional", "short_name": "SMN", "type": "NMHS"}], "language": "es", "news_type": "other", "original_title": "Hay alerta amarilla por lluvias, nevadas y vientos para este lunes 9 de noviembre: las provincias afectadas - LA NACION", "primary_area": "warnings", "relevant": false, "review": false, "summary_en": "Argentina''s national meteorological service (SMN) issued a yellow alert for rain, snow and strong winds affecting eight provinces on 9 November, with gusts possibly above 90 km/h. The item is a routine weather warning with no mention of artificial intelligence.", "summary_original": "El SMN emitió una alerta amarilla por lluvias, nevadas y vientos para el 9 de noviembre en ocho provincias, con ráfagas que pueden superar los 90 km/h.", "system_name": null, "techniques": [], "title_en": "Yellow alert for rain, snow and winds for this Monday 9 November: the provinces affected - LA NACION", "value_added": null, "value_types": [], "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(6760,'claude-haiku-5-5','2026-11-09T04:10:02Z',0,0.97,0,'{"areas": ["warnings"], "confidence": 0.97, "countries": ["CL"], "event_date": "2026-11-09", "institutions": [{"country": "CL", "name": "Servicio Nacional de Prevención y Respuesta ante Desastres", "short_name": "Senapred", "type": "national_ews_agency"}], "language": "es", "news_type": "other", "original_title": "Declaran Alerta Temprana Preventiva en la región Metropolitana por probables tormentas eléctricas", "primary_area": "warnings", "relevant": false, "review": false, "summary_en": "Chile''s national disaster prevention and response service Senapred declared a Preventive Early Warning for the Metropolitan Region due to probable thunderstorms with possible heavy short-duration rainfall. The alert runs from the afternoon of 9 November to the early morning of 10 November 2026. The item does not mention any artificial intelligence.", "summary_original": "Senapred declaró Alerta Temprana Preventiva en la Región Metropolitana por probables tormentas eléctricas con posibles precipitaciones fuertes en corto periodo. La alerta rige desde la tarde del lunes 9 de noviembre hasta la madrugada del martes 10 de noviembre.", "system_name": null, "techniques": [], "title_en": "Preventive Early Warning Declared in the Metropolitan Region due to probable thunderstorms", "value_added": null, "value_types": [], "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(6761,'claude-haiku-5-5','2026-11-09T04:09:49Z',0,0.95,0,'{"areas": ["forecasting"], "confidence": 0.95, "countries": ["MX"], "event_date": "2026-11-08", "institutions": [{"country": "MX", "name": "Servicio Meteorológico Nacional", "short_name": "SMN", "type": "NMHS"}, {"country": "MX", "name": "Comisión Nacional del Agua", "short_name": "Conagua", "type": "other_national_agency"}], "language": "es", "news_type": "other", "original_title": "Clima HOY: México en contraste; SMN pronostica lluvia y frío para el norte mientras las costas del Pacífico suben temperatura este 8 de noviembre", "primary_area": "forecasting", "relevant": false, "review": false, "summary_en": "A routine daily weather forecast from Mexico''s SMN and Conagua describing a cold front interacting with low-pressure troughs, with rain expected in Jalisco. The item contains no mention of artificial intelligence.", "summary_original": "Pronóstico meteorológico diario del SMN y Conagua para México, que describe la interacción de un frente frío con canales de baja presión y lluvias previstas en Jalisco. No menciona inteligencia artificial.", "system_name": null, "techniques": [], "title_en": "Clima HOY: Mexico in contrast; SMN forecasts rain and cold for the north while Pacific coasts rise in temperature this November 8", "value_added": null, "value_types": [], "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(6866,'claude-haiku-5-5','2026-11-10T04:06:36Z',1,0.8,0,'{"areas": ["forecasting"], "confidence": 0.8, "countries": ["US"], "event_date": "2026-11-09", "institutions": [{"country": null, "name": "Journal of Advances in Modeling Earth Systems", "short_name": null, "type": "research"}], "language": "en", "news_type": "pilot_research", "original_title": "AI is helping with hurricane forecasting", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "A study published in the Journal of Advances in Modeling Earth Systems describes AI research aimed at extreme weather forecasts up to six weeks ahead. The article reports that the AI did a much better job forecasting a hurricane landfall near Destin, Florida, though the Atlantic had only one hurricane in the 2026 season.", "summary_original": null, "system_name": null, "techniques": ["ml_dl"], "title_en": "AI is helping with hurricane forecasting", "value_added": "AI research aims at extreme weather forecasts up to six weeks ahead and performed much better than conventional approaches in forecasting a landfall near Destin, Florida.", "value_types": ["lead_time", "accuracy"], "wmo_regions": ["IV"]}');
INSERT INTO "classifications" VALUES(6867,'copied','2026-11-10T04:06:53Z',1,0.85,0,'{"areas": ["forecasting", "warnings"], "confidence": 0.85, "countries": ["US"], "event_date": "2026-11-03", "institutions": [{"country": "US", "name": "National Science Foundation", "short_name": "NSF", "type": "other_national_agency"}], "language": "en", "news_type": "pilot_research", "original_title": "To better predict destructive hail, these scientists are turning to AI", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "Scientists in Colorado and Wyoming, funded by the US National Science Foundation, are using AI to predict destructive hailstorms. The research targets longer warning lead times than the typical 30 minutes offered by current hail warning systems.", "summary_original": null, "system_name": null, "techniques": ["ml_dl"], "title_en": "To better predict destructive hail, these scientists are turning to AI", "value_added": "Aims to improve prediction of destructive hailstorms beyond the roughly 30-minute warning lead time of current systems.", "value_types": ["lead_time", "accuracy"], "wmo_regions": ["IV"]}');
