INSERT INTO "classifications" VALUES(6886,'claude-haiku-5-5','2026-11-10T04:06:48Z',1,0.72,0,'{"areas": ["communication", "warnings"], "confidence": 0.72, "countries": [], "event_date": "2026-11-09", "institutions": [{"country": null, "name": "Unspecified research team", "short_name": null, "type": "research"}], "language": "en", "news_type": "pilot_research", "original_title": "Researchers develop AI tool to improve crisis communication", "primary_area": "communication", "relevant": true, "review": false, "summary_en": "Researchers have developed an AI tool intended to help emergency managers quickly sort reliable information from the large, changing stream of data that emerges during a crisis. The tool targets crisis communication and decision support for disaster response. Snippet details on the specific AI method and deployment are limited.", "summary_original": null, "system_name": null, "techniques": ["ml_dl", "nlp_translation"], "title_en": "Researchers develop AI tool to improve crisis communication", "value_added": "Helps emergency managers distinguish facts from noise in the fast-changing information stream during disasters.", "value_types": ["accuracy", "speed"], "wmo_regions": []}');
INSERT INTO "classifications" VALUES(7023,'claude-haiku-5-5','2026-11-10T04:06:51Z',0,0.9,0,'{"areas": ["other"], "confidence": 0.9, "countries": [], "event_date": "2026-11-09", "institutions": [], "language": "ja", "news_type": "pilot_research", "original_title": "強化学習が世界モデルで劇的に高速化・洗練、ヒューマノイド全身制御のSim-to-Realで久々の革新", "primary_area": "other", "relevant": false, "review": false, "summary_en": "A Japanese tech news article reports a world-model-based technique that speeds up robot reinforcement learning by up to hundreds or a thousand times, applied to humanoid whole-body control. The article concerns robotics rather than weather, water, climate, early warning or disaster risk reduction, so it is not relevant to WMO monitoring.", "summary_original": "世界モデルを応用してロボット強化学習を数百～1000倍近く高速化する技術が登場したと伝える記事。気象・水・気候・防災分野に関係しないロボティクスのニュースである。", "system_name": null, "techniques": ["ml_dl"], "title_en": "Reinforcement learning dramatically accelerated and refined with world models; a breakthrough in humanoid whole-body control via Sim-to-Real", "value_added": null, "value_types": [], "wmo_regions": []}');
