INSERT INTO "classifications" VALUES(7059,'claude-haiku-5-5','2026-11-10T04:06:44Z',0,0.97,0,'{"areas": ["warnings"], "confidence": 0.97, "countries": ["AR"], "event_date": "2026-11-09", "institutions": [{"country": "AR", "name": "Servicio Meteorológico Nacional", "short_name": "SMN", "type": "NMHS"}], "language": "es", "news_type": "other", "original_title": "Alerta meteorológica para este lunes: ocho provincias bajo advertencia por distintos fenómenos", "primary_area": "warnings", "relevant": false, "review": false, "summary_en": "The Argentine National Meteorological Service issued yellow alerts for rain, snow and strong winds affecting eight provinces on Monday 9 November, including snowfall in northwestern Mendoza. The item is a routine weather warning with no mention of artificial intelligence.", "summary_original": "El SMN emitió alertas amarillas por lluvias, nevadas y fuertes vientos para ocho provincias este lunes 9 de noviembre. La alerta por nevadas comprende el noroeste de Mendoza.", "system_name": null, "techniques": [], "title_en": "Weather alert for this Monday: eight provinces under warning for different phenomena", "value_added": null, "value_types": [], "wmo_regions": ["III"]}');
INSERT INTO "classifications" VALUES(7064,'claude-haiku-5-5','2026-11-10T04:06:39Z',1,0.97,0,'{"areas": ["forecasting", "operations", "climate_services"], "confidence": 0.97, "countries": ["PE"], "event_date": null, "institutions": [{"country": "PE", "name": "Servicio Nacional de Meteorología e Hidrología del Perú", "short_name": "SENAMHI", "type": "NMHS"}, {"country": null, "name": "World Meteorological Organization", "short_name": "WMO", "type": "WMO"}], "language": "es", "news_type": "training_capacity", "original_title": "SENAMHI y la OMM fortalecen el uso de inteligencia artificial para la predicción meteorológica en cinco países de Sudamérica", "primary_area": "forecasting", "relevant": true, "review": false, "summary_en": "SENAMHI Peru, together with WMO, opened a regional training workshop on artificial intelligence for operational meteorology and climate services, running from 9 to 13 (month not specified in snippet). The course aims to strengthen AI-based weather forecasting capacity across five South American countries. The initiative targets operational forecasting and climate service capabilities.", "summary_original": "El SENAMHI de Perú, junto con la OMM, inauguró el Curso-Taller Regional sobre Inteligencia Artificial para la Meteorología Operativa y los Servicios Climáticos, que se desarrolla del 9 al 13 para fortalecer la predicción meteorológica con IA en cinco países de Sudamérica.", "system_name": null, "techniques": ["ml_dl", "ai_weather_model"], "title_en": "SENAMHI and WMO strengthen the use of artificial intelligence for weather forecasting in five South American countries", "value_added": "Strengthens regional capacity to use artificial intelligence in operational meteorology and climate services.", "value_types": ["efficiency", "other"], "wmo_regions": ["III"]}');
