INSERT INTO "items" VALUES(645,'https://www.undrr.org/news/strengthening-disaster-risk-governance-south-sudan','https://undrr.org/news/strengthening-disaster-risk-governance-south-sudan','Strengthening disaster risk governance in South Sudan','strengtheningdisasterriskgovernanceinsouthsudan','undrr','UNDRR news','en','2026-10-12T07:47:39Z','2026-10-17T08:55:20Z','From 1 to 5 June 2026, stakeholders convened to validate South Sudan’s Revised Disaster Risk Management Policy. The event was organized by UNDRR in collaboration with South Sudan''s MHADM, FAO, WFP, and IGAD-ICPAC.',1.0,'filtered_out',NULL,NULL);
