INSERT INTO "items" VALUES(2731,'https://www.microsoft.com/en-us/research/blog/flint-interactive-a-language-for-creating-interactive-data-visualizations/','https://microsoft.com/en-us/research/blog/flint-interactive-a-language-for-creating-interactive-data-visualizations','Flint-interactive: A language for creating interactive data visualizations','flintinteractivealanguageforcreatinginteractivedatavisualizations','msr_blog','Microsoft Research blog','en','2026-10-22T16:00:00Z','2026-10-24T03:03:41Z','Flint-interactive gives AI agents a language for creating interactive visualizations. Click a chart, filter data, highlight related content, and explore beyond the view the author originally chose. The post Flint-interactive: A language for creating interactive data visualizations appeared first on Microsoft Research .',1.0,'filtered_out',NULL,NULL);
INSERT INTO "items" VALUES(2732,'https://eos.org/articles/in-northeastern-north-america-alpine-zones-are-turning-green','https://eos.org/articles/in-northeastern-north-america-alpine-zones-are-turning-green','In Northeastern North America, Alpine Zones Are Turning Green','innortheasternnorthamericaalpinezonesareturninggreen','eos','Eos (AGU)','en','2026-10-23T13:25:03Z','2026-10-24T03:03:41Z','These young balsam firs on Mount Mansfield in Vermont are part of a widespread process of alpine zone greening in northeastern North America. Credit: Jonathan Chipman',0.0,'filtered_out',NULL,NULL);
