INSERT INTO "items" VALUES(5628,'https://www.preventionweb.net/publication/documents-and-publications/concurrent-extreme-heat-and-power-outages-health-impacts','https://preventionweb.net/publication/documents-and-publications/concurrent-extreme-heat-and-power-outages-health-impacts','Concurrent extreme heat and power outages: Health impacts, exposure assessment, and research priorities','concurrentextremeheatandpoweroutageshealthimpactsexposureassessmentandresearchpriorities','preventionweb','PreventionWeb','en','2026-11-04T17:59:29Z','2026-11-05T04:00:13Z','This scoping review examines health impacts of concurrent extreme heat and power outages, finding mixed evidence, with respiratory admissions and ambulance attendances among outcomes linked to outages; it calls for better monitoring and preparedness.',0.0,'filtered_out',NULL,NULL);
