INSERT INTO "items" VALUES(5965,'https://phys.org/news/2026-11-isnt-global.html','https://phys.org/news/2026-11-isnt-global.html','Adaptation isn''t keeping up with global warming, UN warns','adaptationisntkeepingupwithglobalwarmingunwarns','phys_earth','Phys.org Earth news','en','2026-11-06T04:00:02Z','2026-11-06T04:01:46Z','With global warming set to exceed 1.5°C, adaptation finance falls far short of needs, implementation is constrained by institutional barriers, and losses and damages are mounting, according to a new report from the United Nations Environment Programme (UNEP).',0.0,'filtered_out',NULL,NULL);
