INSERT INTO "items" VALUES(6860,'https://www.preventionweb.net/vacancy/call-proposals-preparation-first-regular-report-loss-and-damage-associated-adverse-effects','https://preventionweb.net/vacancy/call-proposals-preparation-first-regular-report-loss-and-damage-associated-adverse-effects','Call for proposals: Preparation of the first regular report on loss and damage associated with the adverse effects of climate change','callforproposalspreparationofthefirstregularreportonlossanddamageassociatedwiththeadverseeffectsofclimatechange','preventionweb','PreventionWeb','en','2026-11-09T11:05:46Z','2026-11-10T04:00:26Z','The Santiago Network Secretariat is issuing this call for proposals to select a Lead Drafting Entity to prepare the first edition of the regular report on loss and damage.',1.0,'filtered_out',NULL,NULL);
