INSERT INTO "items" VALUES(6878,'https://eos.org/research-and-developments/many-regions-have-warmed-beyond-1-5c-and-some-beyond-2c-new-study-finds','https://eos.org/research-and-developments/many-regions-have-warmed-beyond-1-5c-and-some-beyond-2c-new-study-finds','Many Regions Have Warmed Beyond 1.5°C and Some Beyond 2°C, New Study Finds','manyregionshavewarmedbeyond15candsomebeyond2cnewstudyfinds','eos','Eos (AGU)','en','2026-11-09T16:01:54Z','2026-11-10T04:04:58Z','Changes to Arctic landscapes caused by global warming have led to decreasing caribou herd numbers across multiple Arctic herds. In line with previous research, a new study found that Earth''s northernmost latitudes are warming the fastest. Credit: NOAA/K. Joly , public domain',1.0,'filtered_out',NULL,NULL);
