INSERT INTO "stories" VALUES(58,'weathernext 2|model_release','forecasting','2026-11-09T04:10:03Z','2026-11-09T04:00:51Z','2026-11-09','{"areas": ["forecasting"], "confidence": 0.8, "countries": [], "event_date": "2026-11-09", "event_name": "WeatherNext 2", "first_seen": "2026-11-09T04:00:51Z", "id": 58, "institution_types": ["private_sector"], "institutions": [{"country": null, "name": "Google DeepMind", "short_name": "DeepMind", "type": "private_sector"}], "languages": ["en"], "last_updated": "2026-11-09T04:00:51Z", "news_type": "model_release", "news_types": ["model_release"], "primary_area": "forecasting", "review": false, "sources": [{"language": "en", "published_at": "2026-11-09T04:00:44Z", "source_name": "dev.to", "title": "AI Daily Digest November 9, 2026: Mistral Opens Le Chonk Weights, Grok API Watermarks by Default, Weather AI Gains a Day - DEV Community", "title_en": "AI Daily Digest November 9, 2026: Mistral Opens Le Chonk Weights, Grok API Watermarks by Default, Weather AI Gains a Day - DEV Community", "url": "https://dev.to/hiroki-ii-ai/ai-daily-digest-november-9-2026-mistral-opens-le-chonk-weights-grok-api-watermarks-by-default-2gdm"}], "summaries_original": {}, "summary_en": "Google DeepMind released code and model weights for WeatherNext Cyclones, the operationalized WeatherNext 2, and the 2-mini variant. The release lets meteorological agencies and researchers build localized AI weather models on top of these systems. This digest item is one of several AI news stories and is a secondary report of the release.", "system_names": ["WeatherNext 2"], "techniques": ["ai_weather_model"], "title": "AI Daily Digest November 9, 2026: Mistral Opens Le Chonk Weights, Grok API Watermarks by Default, Weather AI Gains a Day - DEV Community", "value_added": "Code and model weights released so meteorological agencies and researchers can build localized models on top.", "value_types": ["accessibility"], "wmo_regions": []}');
INSERT INTO "stories" VALUES(59,'','forecasting','2026-11-09T04:10:03Z','2026-11-09T04:05:22Z','2026-11-09','{"areas": ["forecasting", "communication"], "confidence": 0.9, "countries": [{"code": "JP", "name": "Japan"}], "event_date": "2026-11-09", "event_name": null, "first_seen": "2026-11-09T04:05:22Z", "id": 59, "institution_types": ["private_sector"], "institutions": [{"country": "JP", "name": "ウェザーニュース", "short_name": "Weathernews", "type": "private_sector"}], "languages": ["ja"], "last_updated": "2026-11-09T04:05:22Z", "news_type": "operational_implementation", "news_types": ["operational_implementation"], "primary_area": "forecasting", "review": false, "sources": [{"language": "ja", "published_at": "2026-11-09T04:05:18Z", "source_name": "dxmagazine.jp", "title": "【外出や現場の雨対策に】ウェザーニュースの「マイ天気」が進化！AIが1〜3時間先の雨雲の動きをピンポイント予測", "title_en": "Weathernews'' ''My Weather'' evolves: AI predicts rain clouds 1-3 hours ahead for pinpoint local forecasts for outdoor activities and field work", "url": "https://dxmagazine.jp/news/2662ko311/"}], "summaries_original": {"ja": "ウェザーニュースの「マイ天気」がAIで1〜3時間先の雨雲の動きをピンポイント予測する機能を実装したと報じられています。記事では、この機能は予測の高度化であり自治体の避難指示を自動発令するものではないと説明されています。"}, "summary_en": "Weathernews has added an AI-based function to its ''My Weather'' app that predicts rain cloud movement 1-3 hours ahead at pinpoint locations. The article notes the feature improves forecasting precision and does not automatically issue municipal evacuation orders.", "system_names": [], "techniques": ["ml_dl"], "title": "Weathernews'' ''My Weather'' evolves: AI predicts rain clouds 1-3 hours ahead for pinpoint local forecasts for outdoor activities and field work", "value_added": "Pinpoint rain cloud movement prediction 1-3 hours ahead for specific locations, enhancing forecast precision for users.", "value_types": ["accuracy", "lead_time", "resolution"], "wmo_regions": ["II"]}');
INSERT INTO "stories" VALUES(60,'','forecasting','2026-11-10T04:06:53Z','2026-11-10T04:06:29Z','2026-11-10','{"areas": ["forecasting", "climate_services", "operations"], "confidence": 0.97, "countries": [{"code": "PE", "name": "Peru"}], "event_date": "2026-11-10", "event_name": null, "first_seen": "2026-11-10T04:06:29Z", "id": 60, "institution_types": ["NMHS", "WMO"], "institutions": [{"country": "PE", "name": "Servicio Nacional de Meteorología e Hidrología del Perú", "short_name": "SENAMHI", "type": "NMHS"}, {"country": null, "name": "World Meteorological Organization", "short_name": "WMO", "type": "WMO"}], "languages": ["es"], "last_updated": "2026-11-10T04:06:29Z", "news_type": "training_capacity", "news_types": ["training_capacity"], "primary_area": "forecasting", "review": false, "sources": [{"language": "es", "published_at": null, "source_name": "SENAMHI Perú noticias", "title": "SENAMHI y la OMM fortalecen el uso de inteligencia artificial para la predicción meteorológica en cinco países de Sudamérica", "title_en": "SENAMHI and WMO strengthen the use of artificial intelligence for weather forecasting in five South American countries", "url": "https://www.gob.pe/institucion/senamhi/noticias/1471494-senamhi-y-la-omm-fortalecen-el-uso-de-inteligencia-artificial-para-la-prediccion-meteorologica-en-cinco-paises-de-sudamerica"}], "summaries_original": {"es": "El SENAMHI de Perú, junto con la OMM, inauguró el Curso-Taller Regional sobre Inteligencia Artificial para la Meteorología Operativa y los Servicios Climáticos, que se desarrolla del 9 al 13 para fortalecer la predicción meteorológica con IA en cinco países de Sudamérica."}, "summary_en": "SENAMHI Peru, together with WMO, opened a regional training workshop on artificial intelligence for operational meteorology and climate services, running from 9 to 13 (month not specified in snippet). The course aims to strengthen AI-based weather forecasting capacity across five South American countries. The initiative targets operational forecasting and climate service capabilities.", "system_names": [], "techniques": ["ai_weather_model", "ml_dl"], "title": "SENAMHI and WMO strengthen the use of artificial intelligence for weather forecasting in five South American countries", "value_added": "Strengthens regional capacity to use artificial intelligence in operational meteorology and climate services.", "value_types": ["efficiency", "other"], "wmo_regions": ["III"]}');
INSERT INTO "stories" VALUES(61,'','forecasting','2026-11-10T04:06:56Z','2026-11-10T04:04:55Z','2026-11-09','{"areas": ["forecasting"], "confidence": 0.8, "countries": [{"code": "US", "name": "United States"}], "event_date": "2026-11-09", "event_name": null, "first_seen": "2026-11-10T04:04:55Z", "id": 61, "institution_types": ["research"], "institutions": [{"country": null, "name": "Journal of Advances in Modeling Earth Systems", "short_name": null, "type": "research"}], "languages": ["en"], "last_updated": "2026-11-10T04:04:55Z", "news_type": "pilot_research", "news_types": ["pilot_research"], "primary_area": "forecasting", "review": false, "sources": [{"language": "en", "published_at": "2026-11-09T04:04:48Z", "source_name": "cdapress.com", "title": "AI is helping with hurricane forecasting", "title_en": "AI is helping with hurricane forecasting", "url": "https://cdapress.com/news/2026/nov/09/ai-is-helping-with-hurricane-forecasting"}], "summaries_original": {}, "summary_en": "A study published in the Journal of Advances in Modeling Earth Systems describes AI research aimed at extreme weather forecasts up to six weeks ahead. The article reports that the AI did a much better job forecasting a hurricane landfall near Destin, Florida, though the Atlantic had only one hurricane in the 2026 season.", "system_names": [], "techniques": ["ml_dl"], "title": "AI is helping with hurricane forecasting", "value_added": "AI research aims at extreme weather forecasts up to six weeks ahead and performed much better than conventional approaches in forecasting a landfall near Destin, Florida.", "value_types": ["accuracy", "lead_time"], "wmo_regions": ["IV"]}');
INSERT INTO "stories" VALUES(62,'','communication','2026-11-10T04:06:57Z','2026-11-10T04:04:59Z','2026-11-09','{"areas": ["warnings", "communication"], "confidence": 0.72, "countries": [], "event_date": "2026-11-09", "event_name": null, "first_seen": "2026-11-10T04:04:59Z", "id": 62, "institution_types": ["research"], "institutions": [{"country": null, "name": "Unspecified research team", "short_name": null, "type": "research"}], "languages": ["en"], "last_updated": "2026-11-10T04:04:59Z", "news_type": "pilot_research", "news_types": ["pilot_research"], "primary_area": "communication", "review": false, "sources": [{"language": "en", "published_at": "2026-11-09T21:20:13Z", "source_name": "Phys.org Earth news", "title": "Researchers develop AI tool to improve crisis communication", "title_en": "Researchers develop AI tool to improve crisis communication", "url": "https://phys.org/news/2026-11-ai-tool-crisis-communication.html"}], "summaries_original": {}, "summary_en": "Researchers have developed an AI tool intended to help emergency managers quickly sort reliable information from the large, changing stream of data that emerges during a crisis. The tool targets crisis communication and decision support for disaster response. Snippet details on the specific AI method and deployment are limited.", "system_names": [], "techniques": ["ml_dl", "nlp_translation"], "title": "Researchers develop AI tool to improve crisis communication", "value_added": "Helps emergency managers distinguish facts from noise in the fast-changing information stream during disasters.", "value_types": ["accuracy", "speed"], "wmo_regions": []}');
